    public static function get(int $grade): array
    {
        return match ($grade) {
            1 => self::grade1(),
            2 => self::grade2(),
            3 => self::grade3(),
            4 => self::grade4(),
            5 => self::grade5(),
            6 => self::grade6(),
            default => self::grade1(),
        };
    }

